using NvAPIWrapper.GPU;
using VictusPowerUnlockGui;
namespace NvpwrControlBlackwell;
internal sealed partial class MainForm{
 private readonly Dictionary<PcfPowerFields,(NumericUpDown Input,Label Status,Button Apply)> _platformControls=new();
 private readonly Dictionary<PcfPowerFields,PlatformPowerScan> _platformScans=new();
 private void AddPlatformPowerControls(FlowLayoutPanel root){foreach(var field in new[]{PcfPowerFields.ACTargetTPPLimit,PcfPowerFields.ACMaxGPULimit}){
  var card=Card(172,true);card.Dock=DockStyle.None;var title=new Label{Text=field+" (W)",AutoSize=true,Location=new Point(U(16),U(14))};var input=new NumericUpDown{Minimum=0,Maximum=1000,Enabled=false,Location=new Point(U(16),U(50)),Width=U(110)};var scan=ButtonBase("scanPlatform",U(165));scan.Text="Scan laptop / GPU";scan.Location=new Point(U(140),U(44));var apply=ButtonBase("applyPlatform",U(140));apply.Text="Apply";apply.Enabled=false;apply.Location=new Point(U(320),U(44));var status=new Label{Text="Scan for firmware stock/max bounds.",Location=new Point(U(16),U(98)),Size=new Size(U(900),U(56))};card.Resize+=(_,_)=>status.Width=Math.Max(U(220),card.ClientSize.Width-U(32));card.Controls.AddRange(new Control[]{title,input,scan,apply,status});_responsiveWide.Add(card);root.Controls.Add(card);_platformControls[field]=(input,status,apply);
  scan.Click+=async(_,_)=>await ScanPlatformPowerAsync();apply.Click+=async(_,_)=>{if(_busy||!_platformScans.TryGetValue(field,out var info))return;int watts=(int)input.Value;await RunOperationTask(()=>OperationResult.Ok(TppControl.Apply(info,watts)),false);await ScanPlatformPowerAsync();};
 }}
 private async Task ScanPlatformPowerAsync(){if(_busy)return;_busy=true;UpdateWriteButtons();try{foreach(var entry in _platformControls){var c=entry.Value;c.Input.Enabled=false;c.Apply.Enabled=false;_platformScans.Remove(entry.Key);try{var result=await Task.Run(()=>TppControl.Scan(entry.Key));c.Input.Minimum=0;c.Input.Maximum=Math.Max(1000,result.CurrentMw/1000m);c.Input.Value=result.CurrentMw/1000m;_platformScans[entry.Key]=result;c.Status.Text="Current "+(result.CurrentMw/1000m)+" W. "+(result.Adjustable?"Firmware stock "+result.StockW+" W → maximum "+result.MaximumW+" W.":"Stock/max bounds not advertised; adjustment unavailable.");if(result.Adjustable){c.Input.Minimum=0;c.Input.Maximum=result.MaximumW!.Value;c.Input.Minimum=result.StockW!.Value;c.Input.Value=Math.Clamp(result.CurrentMw/1000m,c.Input.Minimum,c.Input.Maximum);c.Input.Enabled=true;c.Apply.Enabled=true;}}catch(Exception ex){c.Status.Text="Scan unavailable: "+ex.Message;}}}finally{_busy=false;UpdateWriteButtons();}}
}
